// Expected keys from Unipile webhook (new_relation)
const body = $('New Relation Event Webhook').first().json.body

const accountId = body.account_id || body.accountId;
const userProviderId = body.user_provider_id || body.userProviderId;
const fullName = body.user_full_name || body.userFullName || "";
const publicIdentifier = body.user_public_identifier || body.userPublicIdentifier || "";
const profileUrl = body.user_profile_url || body.userProfileUrl || "";

const firstName = fullName.trim().split(" ")[0] || "";

if (!accountId || !userProviderId) {
  throw new Error("Webhook payload missing account_id or user_provider_id.");
}

return [{
  json: {
    accountId,          // sender account (the LinkedIn profile that got the connection)
    userProviderId,     // receiver provider_id
    fullName,
    firstName,
    publicIdentifier,
    profileUrl,
    rawWebhook: body
  }
}];

